class ASIK(CommonUnitEndpoint):
    def __init__(self, board_slot, capacity_units):
        # type: (int, List[CapacityUnitEndpoint]) -> None
        master_ip = HardwareIPs.get_cpu_ip(board_slot=board_slot, hw_type='asik', cpu_name='xeon_master')
        super(ASIK, self).__init__(master_ip, capacity_units)

        self.xeon_master_ssh_connection_details = self.master_ssh_connection_details

        xeon_slave_ip = HardwareIPs.get_cpu_ip(board_slot=board_slot, hw_type="asik", cpu_name="xeon_slave")
        self.xeon_slave_ssh_connection_details = SshServiceDetails(addr=xeon_slave_ip,
                                                                   username=self.username,
                                                                   password=self.password)


